extra.setup:
qaBase <- eve_update;
qaClock <- 0.0;
qaStage <- 0;
qaStarted <- 0.0;
eve_update = function(dt) {
    qaBase(dt);
    qaClock += dt;
    if(qaStage==0 && qaClock>0.12) {
        selectLane(3);startAction();
        if(!active)throw "Mantle start rejected: "+lastCode;
        qaStage=1;qaStarted=qaClock;
    } else if(qaStage==1 && !active) {
        if(lastPhase!="completed")throw "Mantle did not complete: "+lastPhase;
        print("CLIMB_MANTLE_COMPLETE_PASS\n");
        selectLane(6);startAction();
        if(!active)throw "Moving platform start rejected: "+lastCode;
        qaStage=2;qaStarted=qaClock;
    } else if(qaStage==2 && !active) {
        if(lastPhase!="completed")throw "Moving action did not complete: "+lastPhase;
        print("CLIMB_MOVING_COMPLETE_PASS\n");qaStage=3;
    }
    if(qaStage<3 && qaClock-qaStarted>3.0)throw "Climbing action timed out";
};
